function buildOrder(model, idName, order) {
  const sort = [];
  // eslint-disable-next-line no-underscore-dangle
  const modelDefinition = this._models && this._models[model];
  const idProperty = modelDefinition && modelDefinition.properties[idName];
  // Only ids generated by the server are missing from _source. Sorting on
  // `_id` needs fielddata, which Elasticsearch 8+ disables by default, so
  // sort on the stored id field whenever there is one.
  const idSortKey = idProperty && idProperty.generated ? '_id' : idName;

  let keys = order;
  if (typeof keys === 'string') {
    keys = keys.split(',');
  }
  for (let index = 0, len = keys.length; index < len; index += 1) {
    const m = keys[index].match(/\s+(A|DE)SC$/);
    let key = keys[index];
    key = key.replace(/\s+(A|DE)SC$/, '').trim();
    if (key === 'id' || key === idName) {
      key = idSortKey;
    }
    if (m && m[1] === 'DE') {
      // sort[key] = -1;
      const temp = {};
      temp[key] = 'desc';
      sort.push(temp);
    } else {
      // sort[key] = 1;
      sort.push(key);
    }
  }

  return sort;
}

module.exports.buildOrder = buildOrder;
